# pywal palette, mapped onto the role names this config used for Catppuccin.
# ~/.config/wal/apply.sh runs :config-source on every wal change.
import json, os

with open(os.path.expanduser("~/.cache/wal/colors.json")) as f:
    _wal = json.load(f)
_c = _wal["colors"]

base = mantle = crust = _wal["special"]["background"]
text = _wal["special"]["foreground"]
subtext1 = subtext0 = _c["color7"]
overlay2 = overlay0 = surface2 = surface1 = _c["color8"]
red = _c["color1"]
green = _c["color2"]
yellow = peach = _c["color3"]
blue = _c["color4"]
mauve = _c["color5"]
teal = sky = _c["color6"]
lavender = _c["color12"]
rosewater = _c["color15"]

